#!/usr/bin/env python3# -*- coding: utf-8 -*-"""reconciliation_engine.pyReusable reconciliation class for:- loading internal and market data- standardizing and validating records- reconciling trades against market prices- generating exception outputs- saving metadata and Tableau-ready detail filesThis class is designed so it can be:1. instantiated directly, or2. inherited by another class and extended."""from __future__ import annotationsimport jsonimport timefrom dataclasses import dataclassfrom pathlib import Pathfrom typing import Callable, Optionalimport pandas as pd@dataclassclass ReconConfig:    internal_file: Path    market_file: Path    output_file: Path    exceptions_file: Path    metadata_file: Path    abs_tolerance: float = 1.0    pct_tolerance: float = 1.0class Reconciliation:    """    Base reconciliation engine.    You can:    - use it directly:        engine = Reconciliation(config)        results = engine.run()    - inherit it:        class CustomReconciliation(Reconciliation):            def classify_breaks(...):                ...    """    REQUIRED_INTERNAL_COLUMNS = {        "trade_id",        "symbol",        "trade_date",        "side",        "quantity",        "trade_price",    }    REQUIRED_MARKET_COLUMNS = {        "symbol",        "date",        "market_close_price",    }    def __init__(        self,        config: ReconConfig,        logger: Optional[Callable[[str], None]] = None,    ) -> None:        self.config = config        self.logger = logger or self.default_logger    # ============================================================    # Logging    # ============================================================    def default_logger(self, message: str) -> None:        print(message)    def log_info(self, message: str) -> None:        self.logger(f"[INFO] {message}")    def log_warn(self, message: str) -> None:        self.logger(f"[WARN] {message}")    def log_error(self, message: str) -> None:        self.logger(f"[ERROR] {message}")    # ============================================================    # Loaders    # ============================================================    def load_csv(self, path: Path, dataset_name: str) -> pd.DataFrame:        if not path.exists():            raise FileNotFoundError(f"{dataset_name} file not found: {path}")        df = pd.read_csv(path)        self.log_info(f"Loaded {dataset_name}: {path} | rows={len(df)}")        return df    def validate_required_columns(        self,        df: pd.DataFrame,        required: set[str],        dataset_name: str,    ) -> None:        missing = required - set(df.columns)        if missing:            raise ValueError(                f"{dataset_name} missing required columns: {sorted(missing)}"            )    # ============================================================    # Standardization    # ============================================================    def standardize_internal_trades(self, df: pd.DataFrame) -> pd.DataFrame:        """        Standardize internal trade input.        Handles strings like 4/1/26 and converts to normalized dates.        """        df = df.copy()        df["trade_id"] = df["trade_id"].astype(str).str.strip()        df["symbol"] = df["symbol"].astype(str).str.upper().str.strip()        df["side"] = df["side"].astype(str).str.upper().str.strip()        # Explicit format avoids ambiguity and warnings.        df["trade_date"] = pd.to_datetime(            df["trade_date"],            format="%m/%d/%y",            errors="coerce",        ).dt.normalize()        df["quantity"] = pd.to_numeric(df["quantity"], errors="coerce")        df["trade_price"] = pd.to_numeric(df["trade_price"], errors="coerce")        return df    def standardize_market_prices(self, df: pd.DataFrame) -> pd.DataFrame:        df = df.copy()        df["symbol"] = df["symbol"].astype(str).str.upper().str.strip()        df["date"] = pd.to_datetime(df["date"], errors="coerce").dt.normalize()        df["market_close_price"] = pd.to_numeric(            df["market_close_price"],            errors="coerce",        )        for col in ["open", "high", "low", "volume"]:            if col in df.columns:                df[col] = pd.to_numeric(df[col], errors="coerce")        return df    # ============================================================    # Controls    # ============================================================    def apply_internal_controls(self, df: pd.DataFrame) -> pd.DataFrame:        df = df.copy()        df["validation_error"] = ""        df.loc[df["trade_id"] == "", "validation_error"] += "Missing trade_id; "        df.loc[df["symbol"] == "", "validation_error"] += "Missing symbol; "        df.loc[df["trade_date"].isna(), "validation_error"] += "Invalid trade_date; "        df.loc[~df["side"].isin(["BUY", "SELL"]), "validation_error"] += "Invalid side; "        df.loc[df["quantity"].isna() | (df["quantity"] <= 0), "validation_error"] += "Invalid quantity; "        df.loc[df["trade_price"].isna() | (df["trade_price"] <= 0), "validation_error"] += "Invalid trade_price; "        duplicate_mask = df["trade_id"].duplicated(keep=False)        df.loc[duplicate_mask, "validation_error"] += "Duplicate trade_id; "        return df    def apply_market_controls(self, df: pd.DataFrame) -> pd.DataFrame:        df = df.copy()        df = df.dropna(subset=["symbol", "date", "market_close_price"])        duplicate_mask = df.duplicated(subset=["symbol", "date"], keep=False)        duplicate_count = int(duplicate_mask.sum())        if duplicate_count > 0:            self.log_warn(                f"Found {duplicate_count} duplicate market rows on symbol/date. "                "Keeping first occurrence."            )            df = df.drop_duplicates(subset=["symbol", "date"], keep="first")        return df    # ============================================================    # Core reconciliation    # ============================================================    def merge_datasets(        self,        internal_df: pd.DataFrame,        market_df: pd.DataFrame,    ) -> pd.DataFrame:        merged = internal_df.merge(            market_df,            how="left",            left_on=["symbol", "trade_date"],            right_on=["symbol", "date"],            suffixes=("", "_market"),        )        merged["market_price_found"] = merged["market_close_price"].notna()        merged["abs_price_diff"] = (            merged["trade_price"] - merged["market_close_price"]        ).abs()        merged["pct_price_diff"] = (            merged["abs_price_diff"] / merged["market_close_price"] * 100.0        )        merged["recon_status"] = ""        merged["exception_reason"] = ""        merged["severity"] = ""        merged["review_action"] = ""        return merged    def classify_breaks(self, merged: pd.DataFrame) -> pd.DataFrame:        """        Default classification logic.        Override this in subclasses if you want custom business rules.        """        merged = merged.copy()        validation_mask = merged["validation_error"].fillna("").str.strip() != ""        merged.loc[validation_mask, "recon_status"] = "VALIDATION_ERROR"        merged.loc[validation_mask, "exception_reason"] = merged.loc[            validation_mask, "validation_error"        ]        merged.loc[validation_mask, "severity"] = "HIGH"        merged.loc[validation_mask, "review_action"] = "Fix trade record and resubmit"        missing_market_mask = (~validation_mask) & (~merged["market_price_found"])        merged.loc[missing_market_mask, "recon_status"] = "MARKET_DATA_MISSING"        merged.loc[missing_market_mask, "exception_reason"] = (            "No market reference price for symbol/date"        )        merged.loc[missing_market_mask, "severity"] = "HIGH"        merged.loc[missing_market_mask, "review_action"] = (            "Review symbol/date and refresh market data"        )        ok_mask = (            (~validation_mask)            & merged["market_price_found"]            & (merged["abs_price_diff"] <= self.config.abs_tolerance)            & (merged["pct_price_diff"] <= self.config.pct_tolerance)        )        merged.loc[ok_mask, "recon_status"] = "MATCHED"        merged.loc[ok_mask, "exception_reason"] = ""        merged.loc[ok_mask, "severity"] = "LOW"        merged.loc[ok_mask, "review_action"] = "No action required"        warning_mask = (            (~validation_mask)            & merged["market_price_found"]            & (merged["recon_status"] == "")            & (                (                    (merged["abs_price_diff"] > self.config.abs_tolerance)                    & (merged["abs_price_diff"] <= self.config.abs_tolerance * 5)                )                |                (                    (merged["pct_price_diff"] > self.config.pct_tolerance)                    & (merged["pct_price_diff"] <= self.config.pct_tolerance * 5)                )            )        )        merged.loc[warning_mask, "recon_status"] = "TOLERANCE_WARNING"        merged.loc[warning_mask, "exception_reason"] = (            "Trade price differs from market price within warning range"        )        merged.loc[warning_mask, "severity"] = "MEDIUM"        merged.loc[warning_mask, "review_action"] = (            "Review pricing source and trade details"        )        critical_mask = (            (~validation_mask)            & merged["market_price_found"]            & (merged["recon_status"] == "")        )        merged.loc[critical_mask, "recon_status"] = "PRICE_BREAK"        merged.loc[critical_mask, "exception_reason"] = (            "Trade price differs materially from market price"        )        merged.loc[critical_mask, "severity"] = "HIGH"        merged.loc[critical_mask, "review_action"] = "Escalate to operations review"        return merged    def finalize_output_columns(self, merged: pd.DataFrame) -> pd.DataFrame:        merged = merged.copy()        merged["business_date"] = merged["trade_date"]        merged["source_system"] = "INTERNAL_TRADES"        merged["processed_timestamp"] = pd.Timestamp.now().floor("s")        output_columns = [            "trade_id",            "symbol",            "trade_date",            "business_date",            "side",            "quantity",            "trade_price",            "market_close_price",            "open",            "high",            "low",            "volume",            "abs_price_diff",            "pct_price_diff",            "recon_status",            "exception_reason",            "severity",            "review_action",            "source_system",            "processed_timestamp",        ]        for col in output_columns:            if col not in merged.columns:                merged[col] = pd.NA        return merged[output_columns].copy()    def reconcile(        self,        internal_df: pd.DataFrame,        market_df: pd.DataFrame,    ) -> pd.DataFrame:        merged = self.merge_datasets(internal_df, market_df)        classified = self.classify_breaks(merged)        return self.finalize_output_columns(classified)    # ============================================================    # Outputs    # ============================================================    def build_exceptions_detail(self, recon_df: pd.DataFrame) -> pd.DataFrame:        exception_statuses = [            "VALIDATION_ERROR",            "MARKET_DATA_MISSING",            "TOLERANCE_WARNING",            "PRICE_BREAK",        ]        exceptions_df = recon_df[            recon_df["recon_status"].isin(exception_statuses)        ].copy()        exceptions_df["assigned_queue"] = exceptions_df["severity"].map(            {                "HIGH": "Priority Operations Queue",                "MEDIUM": "Standard Operations Queue",                "LOW": "Auto-Close Queue",            }        ).fillna("Standard Operations Queue")        return exceptions_df    def save_outputs(        self,        recon_df: pd.DataFrame,        exceptions_df: pd.DataFrame,    ) -> None:        self.config.output_file.parent.mkdir(parents=True, exist_ok=True)        self.config.exceptions_file.parent.mkdir(parents=True, exist_ok=True)        recon_df.to_csv(self.config.output_file, index=False)        exceptions_df.to_csv(self.config.exceptions_file, index=False)        self.log_info(f"Saved reconciliation detail to: {self.config.output_file}")        self.log_info(f"Saved exceptions detail to: {self.config.exceptions_file}")    def save_metadata(        self,        internal_rows: int,        market_rows: int,        recon_rows: int,        exception_rows: int,        runtime_seconds: float,    ) -> None:        metadata = {            "run_timestamp": pd.Timestamp.now().isoformat(),            "config": {                "internal_file": str(self.config.internal_file),                "market_file": str(self.config.market_file),                "output_file": str(self.config.output_file),                "exceptions_file": str(self.config.exceptions_file),                "abs_tolerance": self.config.abs_tolerance,                "pct_tolerance": self.config.pct_tolerance,            },            "row_counts": {                "internal_rows": internal_rows,                "market_rows": market_rows,                "recon_rows": recon_rows,                "exception_rows": exception_rows,            },            "runtime_seconds": round(runtime_seconds, 3),        }        self.config.metadata_file.parent.mkdir(parents=True, exist_ok=True)        self.config.metadata_file.write_text(json.dumps(metadata, indent=2))        self.log_info(f"Saved run metadata to: {self.config.metadata_file}")    # ============================================================    # Main orchestration    # ============================================================    def run(self) -> dict[str, object]:        start_time = time.time()        internal_df = self.load_csv(self.config.internal_file, "internal trades")        market_df = self.load_csv(self.config.market_file, "market prices")        self.validate_required_columns(            internal_df,            self.REQUIRED_INTERNAL_COLUMNS,            "internal trades",        )        self.validate_required_columns(            market_df,            self.REQUIRED_MARKET_COLUMNS,            "market prices",        )        internal_df = self.standardize_internal_trades(internal_df)        market_df = self.standardize_market_prices(market_df)        internal_df = self.apply_internal_controls(internal_df)        market_df = self.apply_market_controls(market_df)        recon_df = self.reconcile(internal_df, market_df)        exceptions_df = self.build_exceptions_detail(recon_df)        self.save_outputs(recon_df, exceptions_df)        runtime_seconds = time.time() - start_time        self.save_metadata(            internal_rows=len(internal_df),            market_rows=len(market_df),            recon_rows=len(recon_df),            exception_rows=len(exceptions_df),            runtime_seconds=runtime_seconds,        )        summary = {            "matched": int((recon_df["recon_status"] == "MATCHED").sum()),            "warnings": int((recon_df["recon_status"] == "TOLERANCE_WARNING").sum()),            "breaks": int((recon_df["recon_status"] == "PRICE_BREAK").sum()),            "missing": int((recon_df["recon_status"] == "MARKET_DATA_MISSING").sum()),            "validation_errors": int((recon_df["recon_status"] == "VALIDATION_ERROR").sum()),            "runtime_seconds": round(runtime_seconds, 3),            "reconciliation_detail": recon_df,            "exceptions_detail": exceptions_df,        }        self.log_info("Reconciliation completed successfully")        self.log_info(f"Matched trades: {summary['matched']}")        self.log_info(f"Warning trades: {summary['warnings']}")        self.log_info(f"Price breaks: {summary['breaks']}")        self.log_info(f"Missing market data: {summary['missing']}")        self.log_info(f"Validation errors: {summary['validation_errors']}")        return summary